import React, { useState, useEffect } from 'react';
import { Save } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

const ProfilePage = () => {
  const navigate = useNavigate();
  const [isLoading, setIsLoading] = useState(true);
  const [profileData, setProfileData] = useState({
    fullName: '',
    bio: '',
    github: '',
    portfolio: ''
  });

  useEffect(() => {
    const fetchProfile = async () => {
      const token = localStorage.getItem('token');
      if (!token) {
        navigate('/');
        return;
      }

      try {
        // الحل هنا: استخدمنا دمج النصوص البسيط بـ + بدلاً من الـ backticks لتجنب أخطاء الكتابة
        const response = await axios.get('http://127.0.0.1:8000/api/profile/', {
          headers: { 
            'Authorization': 'Bearer ' + token 
          }
        });

        if (response.data) {
          setProfileData({
            fullName: response.data.user?.username || '',
            bio: response.data.bio || '',
            github: response.data.github || '',
            portfolio: response.data.portfolio || ''
          });
        }
      } catch (err) {
        console.error("Fetch error:", err);
      } finally {
        setIsLoading(false);
      }
    };

    fetchProfile();
  }, [navigate]);

  if (isLoading) return <div style={{ textAlign: 'center', marginTop: '50px' }}>Loading...</div>;

  return (
    <div style={{ padding: '40px', backgroundColor: '#fdfbff', minHeight: '100vh' }}>
      <div style={{ maxWidth: '850px', margin: '0 auto', backgroundColor: 'white', borderRadius: '15px', padding: '30px' }}>
        <h2 style={{ color: '#4a3f6b' }}>Digital CV Settings</h2>
        
        <div style={{ marginTop: '20px' }}>
          <label style={{ display: 'block', marginBottom: '8px' }}>Full Name</label>
          <input 
            style={{ width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #ddd' }}
            value={profileData.fullName}
            onChange={(e) => setProfileData({...profileData, fullName: e.target.value})}
          />
        </div>

        <button style={{ backgroundColor: '#4a3f6b', color: 'white', padding: '12px 30px', borderRadius: '10px', border: 'none', marginTop: '30px', cursor: 'pointer' }}>
          <Save size={18} style={{ marginRight: '8px' }} /> Save Digital CV
        </button>
      </div>
    </div>
  );
};

export default ProfilePage;
